package com.apiautomation.clients;import java.util.Map;public class AuthApiClient extends ApiClient {public AuthApiClient(String b){super(b);}public io.restassured.response.Response register(String n,String e,String p){return post("/api/auth/register",Map.of("name",n,"email",e,"password",p));}public io.restassured.response.Response registerRaw(Object o){return post("/api/auth/register",o);}public io.restassured.response.Response login(String e,String p){return post("/api/auth/login",Map.of("email",e,"password",p));}public io.restassured.response.Response loginRaw(Object o){return post("/api/auth/login",o);} }
